function blockFits(queries: number[][]): boolean[] {
  const obs: number[] = [];
  const out: boolean[] = [];
  for (const q of queries) {
    if (q[0] === 1) {
      let i = 0;
      while (i < obs.length && obs[i] < q[1]) i++;
      obs.splice(i, 0, q[1]);
    } else {
      const [, x, sz] = q;
      let prev = 0, best = 0;
      for (const o of obs) {
        if (o > x) break;
        best = Math.max(best, o - prev);
        prev = o;
      }
      best = Math.max(best, x - prev);
      out.push(best >= sz);
    }
  }
  return out;
}

