function blockFits(queries: number[][]): boolean[] {
  let X = 1;
  for (const q of queries) X = Math.max(X, q[1]);
  let size = 1;
  while (size < X + 1) size <<= 1;
  const t = new Array(2 * size).fill(0);
  const set = (i: number, v: number) => {
    i += size; t[i] = v;
    for (i >>= 1; i; i >>= 1) t[i] = Math.max(t[2 * i], t[2 * i + 1]);
  };
  const maxUpTo = (hi: number) => { // max over positions [0, hi]
    let res = 0;
    for (let l = size, r = hi + size + 1; l < r; l >>= 1, r >>= 1) {
      if (l & 1) res = Math.max(res, t[l++]);
      if (r & 1) res = Math.max(res, t[--r]);
    }
    return res;
  };
  const obs = [0]; // sorted, 0 acts as an obstacle
  const lastAtMost = (x: number) => { // index of the largest obstacle <= x
    let lo = 0, hi = obs.length - 1;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (obs[mid] <= x) lo = mid; else hi = mid - 1; }
    return lo;
  };
  const out: boolean[] = [];
  for (const q of queries) {
    const x = q[1];
    const i = lastAtMost(x);
    if (q[0] === 1) {
      set(x, x - obs[i]);
      if (i + 1 < obs.length) set(obs[i + 1], obs[i + 1] - x);
      obs.splice(i + 1, 0, x);
    } else {
      const p = obs[i];
      out.push(Math.max(maxUpTo(p), x - p) >= q[2]);
    }
  }
  return out;
}

