class Solution:
    def blockFits(self, queries: List[List[int]]) -> List[bool]:
        X = max(q[1] for q in queries)
        size = 1
        while size < X + 1:
            size <<= 1
        t = [0] * (2 * size)

        def assign(i, v):
            i += size
            t[i] = v
            i >>= 1
            while i:
                t[i] = max(t[2 * i], t[2 * i + 1])
                i >>= 1

        def max_up_to(hi):
            res, l, r = 0, size, hi + size + 1
            while l < r:
                if l & 1:
                    res = max(res, t[l]); l += 1
                if r & 1:
                    r -= 1; res = max(res, t[r])
                l >>= 1; r >>= 1
            return res

        obs, out = [0], []
        for q in queries:
            x = q[1]
            i = bisect.bisect_right(obs, x) - 1
            if q[0] == 1:
                assign(x, x - obs[i])
                if i + 1 < len(obs):
                    assign(obs[i + 1], obs[i + 1] - x)
                obs.insert(i + 1, x)
            else:
                p = obs[i]
                out.append(max(max_up_to(p), x - p) >= q[2])
        return out

